-- Product-owned inert configuration; no execution/scheduling triggers.
CREATE TABLE skills (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), instructions TEXT NOT NULL CHECK(length(instructions) BETWEEN 1 AND 16000 AND length(trim(instructions)) > 0), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)));
CREATE TABLE hooks (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), skill_id TEXT NOT NULL REFERENCES skills(id), agent_id TEXT REFERENCES agents(id), team_id TEXT REFERENCES teams(id), event TEXT NOT NULL CHECK(event IN ('task_created','run_completed','run_failed')), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), CHECK((agent_id IS NULL) != (team_id IS NULL)));
CREATE TABLE loop_policies (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), task_id TEXT NOT NULL REFERENCES tasks(id), max_iterations INTEGER NOT NULL CHECK(max_iterations BETWEEN 1 AND 100), interval_seconds INTEGER NOT NULL CHECK(interval_seconds BETWEEN 60 AND 86400), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)));
